assert len(SECTIONS) == 15, "Expected exactly 15 SEO pages"
assert len(DETAILS) == 15, "Expected matching expanded details on every page"
MARKER = 'data-jb-seo="expanded-2026-10-pro"'
OLD_MARKER = 'data-jb-seo="expanded-2026-10"'
# Homepage improvement: one broad West London heading, visible area-page links
# and a concise service-area introduction. No new doorway pages.

def upgrade_homepage_area_coverage(html):
    old_h1 = '<h1>Roofing & property work, <em>done properly.</em></h1>'
    new_h1 = '<h1>Roofers in <em>West London.</em></h1>'
    if old_h1 in html:
        html = html.replace(old_h1, new_h1, 1)
    else:
        assert new_h1 in html, 'Unexpected homepage H1; inspect before altering it'

    old_intro = ('<p>Professional roofing, property maintenance and building services serving '
                 '<strong>Barnes, Chiswick and surrounding West London areas.</strong></p>')
    new_intro = ('<p>Professional roof repairs, new roofs, flat roofing, gutter repairs, '
                 'chimney and leadwork, and free drone roof inspections where suitable. '
                 'Serving <strong>Barnes, Chiswick, Brentford, Kew, Hammersmith, '
                 'Mortlake, East Sheen and surrounding West London areas.</strong> '
                 'Contact us about 24/7 emergency roofing enquiries.</p>')
    if old_intro in html:
        html = html.replace(old_intro, new_intro, 1)
    else:
        assert new_intro in html, 'Unexpected homepage hero description'

    old_title = '<title>Roofers in Barnes & Chiswick | J.B Property Developments</title>'
    new_title = '<title>Roofers in West London | Barnes & Chiswick | J.B Property Developments</title>'
    if old_title in html:
        html = html.replace(old_title, new_title, 1)
    else:
        assert new_title in html, 'Unexpected homepage title; inspect before changing'

    old_meta = ('<meta name="description" content="Roofers in Barnes and Chiswick. '
                'J.B Property Developments provides roof repairs, new roofs, tile, slate and flat roofing, '
                'fascias, soffits and gutters across West London.">')
    new_meta = ('<meta name="description" content="Roofers in West London covering Barnes, '
                'Chiswick, Brentford, Kew, Hammersmith, Mortlake and East Sheen. '
                'Roof repairs, flat roofs, new roofs, guttering and free drone roof inspections.">')
    if old_meta in html:
        html = html.replace(old_meta, new_meta, 1)
    else:
        assert new_meta in html, 'Unexpected homepage meta description'

    old_area_h = '<h2>Serving Barnes, Chiswick & surrounding West London.</h2>'
    new_area_h = '<h2>Roofing services across West London.</h2>'
    if old_area_h in html:
        html = html.replace(old_area_h, new_area_h, 1)
    else:
        assert new_area_h in html, 'Unexpected homepage areas heading'

    old_area_p = ('<p>J.B Property Developments is based at 15 Harvard Road, W4 4EA, '
                  'serving Barnes, Chiswick and surrounding West London areas. '
                  'Contact us to check your property.</p>')
    new_area_p = ('<p>Our Chiswick business base supports roofing enquiries throughout '
                  'Barnes, Chiswick, Brentford, Kew, Hammersmith, Mortlake, East Sheen '
                  'and neighbouring West London. Choose your area to see the relevant '
                  'roofing information, or contact us with your postcode to confirm '
                  'coverage and availability.</p>')
    if old_area_p in html:
        html = html.replace(old_area_p, new_area_p, 1)
    else:
        assert new_area_p in html, 'Unexpected homepage areas introduction'

    old_areas = ('<div class="area-list"><div>Barnes <small>01</small></div>'
                 '<div>Chiswick <small>02</small></div>'
                 '<div>West London <small>03</small></div>'
                 '<div>Surrounding areas <small>04</small></div></div>')
    destinations = (
        ('Barnes', 'roofers-barnes.html'),
        ('Chiswick', 'roofers-chiswick.html'),
        ('Brentford', 'roofers-brentford.html'),
        ('Kew', 'roofers-kew.html'),
        ('Hammersmith', 'roofers-hammersmith.html'),
        ('Mortlake', 'roofers-mortlake.html'),
        ('East Sheen', 'roofers-east-sheen.html'),
        ('West London', 'roofers-west-london.html'),
    )
    new_areas = ('<div class="area-list">'
                 + ''.join('<div><a href="/' + filename + '">' + name + '</a><small>'
                           + f'{i:02}' + '</small></div>'
                           for i,(name,filename) in enumerate(destinations,1))
                 + '</div>')
    if old_areas in html:
        html = html.replace(old_areas, new_areas, 1)
    else:
        assert new_areas in html, 'Unexpected homepage area grid; inspect before changing'

    old_css = '.area-list small{font-size:12px;color:#81796f}'
    new_css = (old_css + '\n'
               '.area-list a{color:#17202b;text-decoration:none}'
               '.area-list a:hover,.area-list a:focus-visible{color:#815418;text-decoration:underline}')
    if new_css not in html:
        assert old_css in html, 'Expected homepage area-link style not found'
        html=html.replace(old_css,new_css,1)
    for _,destination in destinations:
        assert f'href="/{destination}"' in html, f'Area link missing: {destination}'
    assert len(re.findall(r'<h1\b', html, flags=re.I)) == 1, 'Homepage must have one H1'
    assert html.count('<link rel="canonical" href="https://jbpropertydevelopments.co.uk/">') == 1
    return html

modified = []
for filename, text in SECTIONS.items():
    page = root / filename
    assert page.is_file(), f"Missing expected website page: {filename}"
    original_source = page.read_text(encoding="utf-8")
    html = original_source
    if filename == "index.html":
        html = upgrade_homepage_area_coverage(html)
    if MARKER in html:
        if html != original_source:
            page.write_text(html, encoding="utf-8")
            modified.append(filename)
        continue  # Never add duplicate content if the workflow reruns.
    if filename in {"roofers-barnes.html", "roofers-chiswick.html"}:
        location = "Barnes" if "barnes" in filename else "Chiswick"
        locator = re.compile(
            r'(?=<section>\s*<div class="container">\s*<h2>Looking for a roofer in '
            + location + r'\?</h2>)'
        )
    else:
        locator = re.compile(r'(?=<section class="cta">)')
    matches = list(locator.finditer(html))
    assert len(matches) == 1, f"Expected one contact-section insertion point in {filename}; found {len(matches)}"
    block_class = "section seo-support" if filename == "index.html" else "seo-support"
    section = ('<section class="' + block_class + '" ' + MARKER + '>\n'
               + '<div class="container">\n'
               + dedent(text).strip() + '\n'
               + '<div class="jb-extra-advice">\n'
               + dedent(DETAILS[filename]).strip() + '\n'
               + '</div>\n'
               + '</div>\n</section>\n')
    # The older short expansion is safely upgraded in place, if previously installed.
    if OLD_MARKER in html:
        old_section = re.compile(r'<section\b[^>]*' + re.escape(OLD_MARKER) + r'[^>]*>[\s\S]*?</section>')
        assert len(list(old_section.finditer(html))) == 1, f'Unexpected old SEO section: {filename}'
        html = old_section.sub('', html, count=1)
        matches = list(locator.finditer(html))
        assert len(matches) == 1, f'Lost contact locator while upgrading {filename}'
    original_h1 = len(re.findall(r'<h1\b', html, flags=re.I))
    original_canonical = re.findall(r'<link[^>]+rel=["\']canonical["\'][^>]*>', html, flags=re.I)
    new_html = locator.sub(lambda _m: section, html, count=1)
    assert len(re.findall(r'<h1\b', new_html, flags=re.I)) == original_h1
    assert re.findall(r'<link[^>]+rel=["\']canonical["\'][^>]*>', new_html, flags=re.I) == original_canonical
    assert new_html.count(MARKER) == 1
    styling = ("<style id=\"jb-seo-depth-css\">"
               ".seo-support{background:#f7f6f2;border-top:1px solid #e0ddd5;}"
               ".seo-support .jb-extra-advice{margin-top:25px;padding-top:22px;border-top:1px solid #dcd7cb;}"
               ".seo-support ul{padding-left:1.4em;margin:16px 0 25px;}"
               ".seo-support li{margin:8px 0;line-height:1.65;}"
               ".seo-support h3{margin-top:23px;}"
               ".seo-support a{text-decoration:underline;text-underline-offset:3px;}"
               "</style>")
    if 'id="jb-seo-depth-css"' not in new_html:
        assert '</head>' in new_html
        new_html = new_html.replace('</head>', styling + '\n</head>', 1)
    assert new_html.count('id="jb-seo-depth-css"') == 1
    page.write_text(new_html, encoding="utf-8")
    if filename not in modified:
        modified.append(filename)

print(f"Expanded useful roofing content on {len(modified)} of {len(SECTIONS)} target pages.")
for changed in modified:
    print(" +", changed)


