assert len(PHOTO_ADDITIONS) == 8
PHOTO_MARKER = 'data-jb-project-photos="2026-10"'
photo_css = ("<style id=\"jb-project-photo-css\">"
    ".seo-support .jb-photo-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:20px;}"
    ".seo-support .jb-photo-grid figure{margin:0;border:1px solid #dedbd4;background:white;border-radius:8px;overflow:hidden;}"
    ".seo-support .jb-photo-grid img{display:block;width:100%;height:245px;object-fit:cover;}"
    ".seo-support .jb-photo-grid figcaption{padding:12px 14px;font-size:14px;color:#34404b;}"
    ".seo-support .jb-photo-context{font-size:13px;color:#52616d;margin:15px 0 0;}"
    "@media(max-width:740px){.seo-support .jb-photo-grid{grid-template-columns:1fr;}"
    ".seo-support .jb-photo-grid img{height:auto;max-height:320px;}}"
    "</style>")
for photo_page, photos in PHOTO_ADDITIONS.items():
    target = root / photo_page
    assert target.is_file(), f'Missing local page: {photo_page}'
    original = target.read_text(encoding='utf-8')
    if PHOTO_MARKER in original:
        assert original.count(PHOTO_MARKER) == 1, f'Duplicate photo block in {photo_page}'
        continue
    assert MARKER in original, f'SEO expansion missing on {photo_page}'
    assert original.count(MARKER) == 1, f'Unexpected multiple SEO sections: {photo_page}'
    assert original.count('</head>') == 1
    assert len(photos) in (1, 2)
    heading = ('A closer look at roof details' if len(photos) == 1
               else 'Roofing details from our project gallery')
    figures = ''.join(
        '<figure><img loading="lazy" decoding="async" src="' + path + '" alt="' + alt + '">'
        '<figcaption>' + caption + '</figcaption></figure>'
        for path, alt, caption in photos
    )
    note = '<p class="jb-photo-context">Photographs are from our existing roofing gallery. The individual job locations are not assigned to this area without verification.</p>'
    photo_section = ('<div class="jb-local-photos" ' + PHOTO_MARKER + '>'
                     '<h3>' + heading + '</h3><div class="jb-photo-grid">'
                     + figures + '</div>' + note + '</div>')
    # The existing SEO support section contains no nested <section> tags.
    seo_pattern = re.compile(r'(<section\b[^>]*' + re.escape(MARKER) + r'[^>]*>[\s\S]*?)(</section>)')
    assert len(seo_pattern.findall(original)) == 1, 'Expected one expanded advice section'
    updated = seo_pattern.sub(lambda m: m.group(1) + '\n' + photo_section + '\n' + m.group(2), original, count=1)
    if 'id="jb-project-photo-css"' not in updated:
        updated = updated.replace('</head>', photo_css + '\n</head>', 1)
    assert updated.count(PHOTO_MARKER) == 1
    assert updated.count('id="jb-project-photo-css"') == 1
    assert len(re.findall(r'<h1\b', updated, re.I)) == len(re.findall(r'<h1\b', original, re.I))
    assert re.findall(r'<link[^>]+rel=["\']canonical["\'][^>]*>', updated, re.I) == re.findall(r'<link[^>]+rel=["\']canonical["\'][^>]*>', original, re.I)
    target.write_text(updated, encoding='utf-8')
    print('Included existing roofing portfolio photography:', photo_page)

