_jb_photo_dir = root / "assets"
_jb_photo_dir.mkdir(exist_ok=True)
_jb_new_photo_paths = []
for _jb_fname, _jb_chunks in ILLUSTRATIVE_BYTES.items():
    _jb_bytes = _jb_base64.b64decode("".join(_jb_chunks), validate=True)
    assert _jb_bytes.startswith(b"\xff\xd8\xff"), "Expected valid JPG image"
    _jb_target = _jb_photo_dir / _jb_fname
    if _jb_target.exists():
        assert _jb_target.read_bytes() == _jb_bytes, "An existing illustrative photo differs: " + _jb_fname
    else:
        _jb_target.write_bytes(_jb_bytes)
        _jb_new_photo_paths.append("assets/" + _jb_fname)
ILLUSTRATION_MARKER = 'data-jb-illustration="2026-10"'
ILLUSTRATION_STYLE = ('<style id="jb-illustration-css">'
    ".seo-support .jb-illustration{margin:28px 0 0;max-width:520px;}"
    ".seo-support .jb-illustration img{display:block;width:100%;height:290px;object-fit:cover;border-radius:8px;}"
    ".seo-support .jb-illustration figcaption{font-size:13px;line-height:1.55;color:#55636f;margin-top:9px;}"
    "@media(max-width:740px){.seo-support .jb-illustration img{height:auto;max-height:420px;}}"
    "</style>")
for _jb_page, (_jb_fname, _jb_desc) in ILLUSTRATION_PLACEMENTS.items():
    _jb_path = root / _jb_page
    _jb_before = _jb_path.read_text(encoding="utf-8")
    if ILLUSTRATION_MARKER in _jb_before:
        assert _jb_before.count(ILLUSTRATION_MARKER) == 1, "Duplicate illustrative photo block: " + _jb_page
        continue
    assert MARKER in _jb_before, "Missing helpful SEO copy: " + _jb_page
    _jb_note = "Illustrative roofing example (not a photograph of a J.B Property Developments customer job)."
    _jb_alt = "Illustrative image: " + _jb_desc
    _jb_photo = ('<figure class="jb-illustration" ' + ILLUSTRATION_MARKER + '><img loading="lazy" decoding="async"'
        ' width="300" height="500" src="/assets/' + _jb_fname + '" alt="' + _jb_alt + '">'
        '<figcaption>' + _jb_note + '</figcaption></figure>')
    _jb_pattern = re.compile(r'(<section\b[^>]*' + re.escape(MARKER) + r'[^>]*>[\s\S]*?)(</section>)')
    assert len(_jb_pattern.findall(_jb_before)) == 1, "SEO content section missing: " + _jb_page
    _jb_after = _jb_pattern.sub(lambda m: m.group(1) + "\n" + "".join(_jb_photo) + "\n" + m.group(2), _jb_before, count=1)
    assert _jb_after.count(ILLUSTRATION_MARKER) == 1
    if 'id="jb-illustration-css"' not in _jb_after:
        assert _jb_after.count("</head>") == 1
        _jb_after = _jb_after.replace("</head>", "".join(ILLUSTRATION_STYLE) + "\n</head>", 1)
    assert len(re.findall(r"<h1\b", _jb_after, flags=re.I)) == len(re.findall(r"<h1\b", _jb_before, flags=re.I))
    assert re.findall(r'<link[^>]+rel=["\']canonical["\'][^>]*>', _jb_after, flags=re.I) == re.findall(r'<link[^>]+rel=["\']canonical["\'][^>]*>', _jb_before, flags=re.I)
    _jb_path.write_text(_jb_after, encoding="utf-8")
    print("Added labelled illustrative detail:", _jb_page)
# The pre-existing GitHub Actions workflow commits *.html only. Stage the
# newly installed image files here so the same workflow commit contains them.
if _jb_new_photo_paths and (root / ".git").exists():
    _jb_subprocess.run(["git", "add", "--", *_jb_new_photo_paths], cwd=str(root), check=True)
print("New illustrative photo assets:", len(_jb_new_photo_paths), "; pages with supporting visuals:", len(ILLUSTRATION_PLACEMENTS))


